    public void Execute(ReadonlyExecutionResult result)
    {
        var transforms = Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
        foreach (var t in transforms)
        {
            if (t.name.Contains("Spawn") || t.name.Contains("WorldStart") || t.name.Contains("Market") || t.name.Contains("Manager") || t.name.Contains("Platform"))
            {
                result.Log("Object: {0}, path: {1}, components: {2}", t.name, GetPath(t), string.Join(", ", GetComponents(t)));
            }
        }
    }

    private string GetPath(Transform t)
    {
        if (t.parent == null) return t.name;
        return GetPath(t.parent) + "/" + t.name;
    }

    private string[] GetComponents(Transform t)
    {
        var comps = t.GetComponents<Component>();
        var names = new string[comps.Length];
        for (int i = 0; i < comps.Length; i++)
        {
            names[i] = comps[i] != null ? comps[i].GetType().Name : "null";
        }
        return names;
    }
}

