internal class CommandScript : IReadonlyRunCommand
{
    public void Execute(ReadonlyExecutionResult result)
    {
        var scene = SceneManager.GetActiveScene();
        DumpGameObject(scene.GetRootGameObjects(), "", result);
    }

    private void DumpGameObject(GameObject[] objs, string indent, ReadonlyExecutionResult result)
    {
        foreach (var obj in objs)
        {
            var compNames = "";
            foreach (var c in obj.GetComponents<Component>())
            {
                if (c != null) compNames += c.GetType().Name + " ";
            }
            result.Log("{0}{1} [{2}]", indent, obj.name, compNames);
            if (obj.transform.childCount > 0)
            {
                var children = new GameObject[obj.transform.childCount];
                for (int i = 0; i < obj.transform.childCount; i++)
                {
                    children[i] = obj.transform.GetChild(i).gameObject;
                }
                DumpGameObject(children, indent + "  ", result);
            }
        }
    }
}

