using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var marketScene = EditorSceneManager.OpenScene("Assets/Scene/Scenes/MarketSquare.unity", OpenSceneMode.Single);

        var ground = GameObject.Find("MarketGround");
        if (ground != null)
        {
            result.Log("MarketGround layer: {0} ({1}), pos: {2}", ground.layer, LayerMask.LayerToName(ground.layer), ground.transform.position);
            var cols = ground.GetComponents<Collider>();
            foreach (var col in cols)
            {
                result.Log("  Collider: {0}, isTrigger: {1}, bounds: {2}", col.GetType().Name, col.isTrigger, col.bounds);
                if (col is MeshCollider mc)
                {
                    result.Log("  MeshCollider sharedMesh: {0}, convex: {1}", mc.sharedMesh != null ? mc.sharedMesh.name : "null", mc.convex);
                }
            }
        }
        else
        {
            result.Log("MarketGround not found!");
        }

        var spawn = GameObject.Find("MarketSquareWorldSpawn");
        if (spawn != null)
        {
            result.Log("MarketSquareWorldSpawn pos: {0}", spawn.transform.position);
        }

        var playerPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PrefabInstance/PlayerAndCamera.prefab");
        if (playerPrefab != null)
        {
            var pm = playerPrefab.GetComponentInChildren<PlayerMovement>(true);
            if (pm != null)
            {
                var so = new SerializedObject(pm);
                var whatIsGround = so.FindProperty("whatIsGround");
                if (whatIsGround != null)
                {
                    result.Log("PlayerMovement whatIsGround layerMask: {0} (layer names: {1})", whatIsGround.intValue, LayerMaskToString(whatIsGround.intValue));
                }
            }
        }
    }

    private string LayerMaskToString(int mask)
    {
        var layers = new System.Collections.Generic.List<string>();
        for (int i = 0; i < 32; i++)
        {
            if ((mask & (1 << i)) != 0)
            {
                layers.Add(LayerMask.LayerToName(i) + "(" + i + ")");
            }
        }
        return string.Join(", ", layers);
    }
}

