internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var marketScene = EditorSceneManager.OpenScene("Assets/Scene/Scenes/MarketSquare.unity", OpenSceneMode.Single);

        var colliders = Object.FindObjectsByType<Collider>(FindObjectsSortMode.None);
        result.Log("Total colliders in MarketSquare: {0}", colliders.Length);

        var groundLayer = LayerMask.NameToLayer("Ground");
        var playerLayer = LayerMask.NameToLayer("Player");
        var defaultLayer = LayerMask.NameToLayer("Default");
        var interactLayer = LayerMask.NameToLayer("Interact");
        var objectLayer = LayerMask.NameToLayer("Object");

        int defaultCount = 0;
        int groundCount = 0;
        int objectCount = 0;
        int otherCount = 0;

        foreach (var col in colliders)
        {
            int l = col.gameObject.layer;
            if (l == defaultLayer) defaultCount++;
            else if (l == groundLayer) groundCount++;
            else if (l == objectLayer) groundCount++;
            else otherCount++;

            result.Log("Collider: {0} ({1}), layer: {2} ({3}), isTrigger: {4}", 
                col.name, col.GetType().Name, l, LayerMask.LayerToName(l), col.isTrigger);
        }

        result.Log("Summary: Default={0}, Ground/Obj={1}, Other={2}", defaultCount, groundCount, otherCount);
    }
}

