using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var marketScene = EditorSceneManager.OpenScene("Assets/Scene/Scenes/MarketSquare.unity", OpenSceneMode.Single);

        int groundLayer = LayerMask.NameToLayer("Ground");
        int objectLayer = LayerMask.NameToLayer("Object");

        // 1. MarketGround setup
        var ground = GameObject.Find("MarketGround");
        if (ground != null)
        {
            ground.layer = groundLayer;

            // Remove existing mesh collider if any or keep it and add a solid thick BoxCollider
            var mc = ground.GetComponent<MeshCollider>();
            if (mc != null)
            {
                Object.DestroyImmediate(mc);
            }

            var bc = ground.GetComponent<BoxCollider>();
            if (bc == null)
            {
                bc = ground.AddComponent<BoxCollider>();
                result.RegisterObjectCreation(bc);
            }

            // The plane has scale 111, 1, 111.
            // Plane mesh in Unity default is 10x10 units (so with scale 111 it is 1110 x 1110 units).
            // In local space, size should be (10, 4, 10), center (0, -2, 0).
            bc.center = new Vector3(0f, -2f, 0f);
            bc.size = new Vector3(10f, 4f, 10f);

            result.RegisterObjectModification(ground);
            result.Log("Updated MarketGround layer to Ground (9) and added thick BoxCollider: center {0}, size {1}", bc.center, bc.size);
        }

        // 2. Cylinder spawn pad
        var cyl = GameObject.Find("Cylinder");
        if (cyl != null)
        {
            cyl.layer = groundLayer;
            result.RegisterObjectModification(cyl);
            result.Log("Updated Cylinder layer to Ground (9)");
        }

        // 3. WorldStartPlatform
        var platform = GameObject.Find("WorldStartPlatform");
        if (platform != null)
        {
            platform.layer = groundLayer;
            result.RegisterObjectModification(platform);
            result.Log("Updated WorldStartPlatform layer to Ground (9)");
        }

        // 4. Adjust MarketSquareWorldSpawn height so players spawn safely standing on ground
        var spawn = GameObject.Find("MarketSquareWorldSpawn");
        if (spawn != null)
        {
            spawn.transform.position = new Vector3(25.08f, 1.2f, -13.93f);
            result.RegisterObjectModification(spawn);
            result.Log("Updated MarketSquareWorldSpawn position to {0}", spawn.transform.position);
        }

        // 5. Update Preset_Tavern_01 objects
        var tavern = GameObject.Find("Preset_Tavern_01");
        if (tavern != null)
        {
            int floorsUpdated = 0;
            int objectsUpdated = 0;

            foreach (var tr in tavern.GetComponentsInChildren<Transform>(true))
            {
                if (tr == tavern.transform) continue;

                var col = tr.GetComponent<Collider>();
                if (col != null)
                {
                    string nameLower = tr.name.ToLower();
                    if (nameLower.Contains("floor") || nameLower.Contains("stair") || nameLower.Contains("ground") || nameLower.Contains("ramp"))
                    {
                        tr.gameObject.layer = groundLayer;
                        floorsUpdated++;
                    }
                    else
                    {
                        tr.gameObject.layer = objectLayer;
                        objectsUpdated++;
                    }
                    result.RegisterObjectModification(tr.gameObject);
                }
            }
            result.Log("Updated Tavern colliders: {0} floors to Ground layer, {1} items to Object layer", floorsUpdated, objectsUpdated);
        }

        EditorSceneManager.SaveScene(marketScene);
        result.Log("Saved MarketSquare scene with corrected physics layers!");
    }
}

