using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var marketScene = EditorSceneManager.OpenScene("Assets/Scene/Scenes/MarketSquare.unity", OpenSceneMode.Single);

        var oiObj = GameObject.Find("===Managers===/OtherInput");
        var uiCanvas = GameObject.Find("UI (1)");

        if (oiObj != null && uiCanvas != null)
        {
            var oi = oiObj.GetComponent<OtherInput>();

            oi.crosshair = uiCanvas.transform.Find("Crosshair")?.gameObject;
            oi.hotbar = uiCanvas.transform.Find("Hotkeys")?.gameObject;
            oi.pauseUi = uiCanvas.transform.Find("PauseUI")?.gameObject;
            oi.settingsUi = uiCanvas.transform.Find("Settings")?.gameObject;

            var craftingLayout = uiCanvas.transform.Find("CraftingNew/CraftingLayout");
            if (craftingLayout != null)
            {
                oi.creative = craftingLayout.Find("Creative")?.gameObject;
                oi.handcrafts = craftingLayout.Find("Handcrafting")?.gameObject;
                oi.workbench = craftingLayout.Find("WorkbenchNew")?.gameObject;
                oi.fletch = craftingLayout.Find("FletchingNew")?.gameObject;
                oi.anvil = craftingLayout.Find("AnvilNew")?.gameObject;
                oi.furnace = craftingLayout.Find("FurnaceNew")?.gameObject;
                oi.cauldron = craftingLayout.Find("CauldronNew")?.gameObject;
                oi.chest = craftingLayout.Find("Chest")?.gameObject;
            }

            var sfxObj = GameObject.Find("Audio/Sfx");
            if (sfxObj != null)
            {
                oi.UiSfx = sfxObj.GetComponent<UiSfx>();
            }

            result.RegisterObjectModification(oi);
            result.Log("Wired OtherInput UI references successfully: pauseUi={0}, settingsUi={1}, hotbar={2}, crosshair={3}",
                oi.pauseUi?.name, oi.settingsUi?.name, oi.hotbar?.name, oi.crosshair?.name);
        }

        // Also check if World has a water transform or dummy water plane
        var worldObj = GameObject.Find("===World===");
        if (worldObj != null)
        {
            var world = worldObj.GetComponent<World>();
            if (world != null && world.water == null)
            {
                // Create a dummy water transform positioned at y = -1000 so player is never under water in MarketSquare
                var dummyWater = new GameObject("Water");
                dummyWater.transform.SetParent(worldObj.transform);
                dummyWater.transform.position = new Vector3(0, -1000f, 0);
                world.water = dummyWater.transform;
                result.RegisterObjectCreation(dummyWater);
                result.RegisterObjectModification(world);
                result.Log("Created dummy water reference at y=-1000 in MarketSquare");
            }
        }

        EditorSceneManager.SaveScene(marketScene);
        result.Log("MarketSquare saved successfully!");
    }
}

