using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scene = EditorSceneManager.OpenScene("Assets/Scene/Scenes/MarketSquare.unity", OpenSceneMode.Single);

        var triggers = Object.FindObjectsByType<MarketSquarePlatformTrigger>(FindObjectsSortMode.None);
        result.Log("Found {0} MarketSquarePlatformTrigger components", triggers.Length);
        foreach (var t in triggers)
        {
            var col = t.GetComponent<Collider>();
            var rb = t.GetComponent<Rigidbody>();
            result.Log("Trigger GO: {0}, Layer: {1} ({2}), Collider: {3}, isTrigger: {4}, Rigidbody: {5}, bounds: {6}",
                t.gameObject.name, t.gameObject.layer, LayerMask.LayerToName(t.gameObject.layer),
                col != null ? col.GetType().Name : "none",
                col != null ? col.isTrigger.ToString() : "n/a",
                rb != null ? "yes, isKinematic=" + rb.isKinematic : "no",
                col != null ? col.bounds.ToString() : "n/a");
        }

        var mgrs = Object.FindObjectsByType<MarketSquareManager>(FindObjectsSortMode.None);
        result.Log("Found {0} MarketSquareManager components", mgrs.Length);
        foreach (var m in mgrs)
        {
            result.Log("MarketSquareManager GO: {0}, platformTrigger ref: {1}, worldSpawn ref: {2}",
                m.gameObject.name, m.platformTrigger, m.worldSpawn);
        }

        // Check Player prefabs
        var playerPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PrefabInstance/PlayerAndCamera.prefab");
        if (playerPrefab != null)
        {
            var cols = playerPrefab.GetComponentsInChildren<Collider>(true);
            var pm = playerPrefab.GetComponentInChildren<PlayerManager>(true);
            var rb = playerPrefab.GetComponentInChildren<Rigidbody>(true);
            result.Log("PlayerAndCamera: PM={0} on {1}, RB={2}, Colliders count={3}",
