                result.Log("  PlayerAndCamera Col: {0} ({1}), layer: {2} ({3}), isTrigger: {4}",
                    c.gameObject.name, c.GetType().Name, c.gameObject.layer, LayerMask.LayerToName(c.gameObject.layer), c.isTrigger);
            }
        }

        var onlinePlayerPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PrefabInstance/OnlinePlayer.prefab");
        if (onlinePlayerPrefab != null)
