internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PrefabInstance/PlayerAndCamera.prefab");
        result.Log("--- PlayerAndCamera Structure ---");
        PrintTransform(prefab.transform, 0, result);
    }

    void PrintTransform(Transform t, int depth, ExecutionResult result)
    {
        string indent = new string(' ', depth * 2);
        var rbs = t.GetComponents<Rigidbody>();
        var cols = t.GetComponents<Collider>();
        var pms = t.GetComponents<PlayerManager>();
        var scripts = t.GetComponents<MonoBehaviour>();

        string info = $"{indent}- {t.gameObject.name} (layer: {t.gameObject.layer} - {LayerMask.LayerToName(t.gameObject.layer)})";
        if (rbs.Length > 0) info += " [RB: isKinematic=" + rbs[0].isKinematic + "]";
        if (cols.Length > 0)
        {
            foreach (var c in cols) info += $" [Col: {c.GetType().Name}, trigger={c.isTrigger}]";
        }
        if (pms.Length > 0) info += " [PlayerManager]";
        foreach (var s in scripts)
        {
            if (s != null && !(s is PlayerManager)) info += $" [{s.GetType().Name}]";
        }
        result.Log(info);

        for (int i = 0; i < t.childCount; i++)
        {
            PrintTransform(t.GetChild(i), depth + 1, result);
        }
    }
}

