namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            // Open GameAfterLobby scene
            EditorSceneManager.OpenScene("Assets/Scene/Scenes/GameAfterLobby.unity", OpenSceneMode.Single);
            var gm = Object.FindAnyObjectByType<GameManager>();
            if (gm != null)
            {
                result.Log("GameManager gameoverUi: {0}", gm.gameoverUi != null ? gm.gameoverUi.name : "null");
                if (gm.gameoverUi != null)
                {
                    PrintHierarchy(gm.gameoverUi.transform, 0, result);
                }
            }

            // Search for all Buttons in GameAfterLobby scene
            var buttons = Object.FindObjectsByType<Button>(FindObjectsInactive.Include, FindObjectsSortMode.None);
            result.Log("Total buttons in GameAfterLobby: {0}", buttons.Length);
            foreach (var b in buttons)
            {
                var txt = b.GetComponentInChildren<TextMeshProUGUI>(true);
                var legacyTxt = b.GetComponentInChildren<Text>(true);
                string label = txt != null ? txt.text : (legacyTxt != null ? legacyTxt.text : "no text");
                result.Log("Button: {0} (parent: {1}), text='{2}', active={3}", b.gameObject.name, b.transform.parent != null ? b.transform.parent.name : "root", label, b.gameObject.activeInHierarchy);
                int count = b.onClick.GetPersistentEventCount();
                for (int i = 0; i < count; i++)
                {
                    result.Log("  onClick[{0}]: Target={1}, Method={2}", i, b.onClick.GetPersistentTarget(i), b.onClick.GetPersistentMethodName(i));
                }
            }
        }

        void PrintHierarchy(Transform t, int depth, ExecutionResult result)
        {
            string indent = new string (' ', depth * 2);
            var txt = t.GetComponent<TextMeshProUGUI>();
            var btn = t.GetComponent<Button>();
            string info = $"{indent}- {t.gameObject.name} (active: {t.gameObject.activeSelf})";
            if (txt != null)
                info += $" [TMP: '{txt.text}']";
            if (btn != null)
                info += " [Button]";
            result.Log(info);
            for (int i = 0; i < t.childCount; i++)
            {
                PrintHierarchy(t.GetChild(i), depth + 1, result);
            }
        }
    }
}

